// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    DepositLog c;

    function setUp() public { c = new DepositLog(); }

    function testFuzz_property(
        address requester,
        bytes32 digest,
        uint256 utxoSize,
        bytes memory redeemerOutputScript,
        uint256 requestedFee,
        bytes memory outpoint
    ) public {
        vm.assume(requester != address(0));
        // Owner is address(0) by default; approve a fresh logger from the owner.
        address logger = address(0xBEEF);
        vm.prank(address(0));
        c.setApprovedLogger(logger, true);
        assertTrue(c.approvedToLog(logger));

        vm.prank(logger);
        bool ok = c.logRedemptionRequested(
            requester,
            digest,
            utxoSize,
            redeemerOutputScript,
            requestedFee,
            outpoint
        );
        // Rule: an approved logger's completed logRedemptionRequested call returns true.
        assertTrue(ok);
    }
}
